/bin/bash -lc "node -e '
const fs = require(\"fs\");
const p = \"/workspace/result.json\";
const x = JSON.parse(fs.readFileSync(p, \"utf8\"));
const exact = JSON.stringify(Object.keys(x)) === JSON.stringify([\"total_cents\",\"order_count\",\"duplicates_skipped\",\"by_region\"]);
const regions = JSON.stringify(Object.keys(x.by_region)) === JSON.stringify([\"north\",\"south\",\"east\",\"west\"]);
const integerValues = [x.total_cents,x.order_count,x.duplicates_skipped,...Object.values(x.by_region)].every(Number.isInteger);
const regionSum = Object.values(x.by_region).reduce((a,b)=>a+b,0);
if ("'!exact || !regions || !integerValues || regionSum !== x.total_cents) process.exit(1);
console.log(JSON.stringify({valid_json:true, exact_keys:exact, integer_values:integerValues, region_sum:regionSum, matches_total:regionSum===x.total_cents}));
'"'"

